input.value:
// routed = matches the route condition; processed = the pipeline added nexus.cluster
fetch logs
| filter startsWith(aws.log_group, "/aws/ecs/srv/")
| fieldsAdd routed = matchesValue(aws.log_group, "/aws/ecs/srv/*") and (matchesValue(aws.log_group, "*-adapter") or matchesValue(aws.log_group, "*-mngr")), processed = isNotNull(nexus.cluster)
| summarize lines = count(), by: { aws.log_group, routed, processed }
| sort aws.log_group asc

// counts only, so no customer document is shown if the masking fails
fetch logs
| filter matchesValue(content, "*X-CustIdentNum=*")
| fieldsAdd content = replacePattern(content, "'X-CustIdentNum=' LD ','", "X-CustIdentNum=####,")
| summarize lines = count(), masked = countIf(contains(content, "X-CustIdentNum=####,")), by: { aws.log_group }

// expected: bck-nexus-error-log only with should_be_error = true, logs_integracion only with false
fetch logs
| filter in(dt.system.bucket, array("logs_integracion", "bck-nexus-error-log")) and isNotNull(nexus.cluster)
| fieldsAdd should_be_error = coalesce(matchesValue(nexus.kind, "mapping_error") or matchesValue(nexus.kind, "timeout_504") or matchesValue(nexus.kind, "technical_error") or matchesValue(nexus.kind, "mngr_error") or matchesValue(nexus.kind, "stratus_late_reply") or matchesValue(nexus.kind, "stream_*") or matchesValue(nexus.outcome, "error") or matchesValue(nexus.acceptance, "M"), false)
| summarize lines = count(), by: { dt.system.bucket, should_be_error }

timeseries r = sum(custom.nexus.log.adapter.responses), by: { outcome }
| fieldsAdd responses = arraySum(r)
| fields outcome, responses

fetch logs
| filter dt.system.bucket == "bck-nexus-error-log" and nexus.kind == "mngr_error"
| summarize logs = count(), by: { nexus.cluster }
| lookup [
    timeseries m = sum(custom.nexus.log.mngr.errors), by: { cluster }
    | fieldsAdd metric = arraySum(m)
  ], sourceField: nexus.cluster, lookupField: cluster, fields: { metric }
| fieldsAdd diff_pct = round(100.0 * (coalesce(metric, 0) - logs) / logs, decimals: 1)
| sort diff_pct asc
